export function getTollPlazasForHighway(highwayNumber: string): FastagTollPlaza[] {
  const hw = highwayNumber.toUpperCase().trim();
  return Object.values(FASTAG_TOLL_PLAZA_REGISTRY).filter(p => p.highwayNumber.toUpperCase().includes(hw));
}

export function estimateRouteTollCost(plazaIds: string[], isMultiAxle: boolean = false): number {
  return plazaIds.reduce((sum, pid) => {
    const plaza = FASTAG_TOLL_PLAZA_REGISTRY[pid];
    if (!plaza) return sum;
    return sum + (isMultiAxle ? plaza.multiAxleBusSingleTollINR : plaza.twoAxleBusSingleTollINR);
  }, 0);
}
